// Hybrid PowerPC 603e core: statically recompiled code plus Supermodel's interpreter.
//
// This file compiles Supermodel's interpreter (ppc.cpp) in its own translation unit,
// renaming its ppc_execute() and ppc_attach_bus(), and provides replacements. The
// rest of Supermodel (Model3.cpp, the frontend) calls the normal ppc_* API and
// cannot tell the difference.
//
// Execution model
//   ppc_execute(cycles) runs a dispatch loop. For each guest PC it looks up a
//   recompiled unit (generated by tools/ppcrecomp). Units run whole basic blocks
//   natively and return to the dispatcher on calls, returns, indirect jumps and
//   exceptions. When there is no unit for a PC, or a block would cross the end of
//   the cycle budget or a decrementer tick, the dispatcher interprets that block
//   with the original interpreter instead. Results therefore match the stock
//   interpreter instruction for instruction, which tests/lockstep relies on.
//
// Environment variables
//   ECA_PPC_MODE=interp     never run recompiled code (dispatcher + interpreter only)
//   ECA_PPC_MODE=stock      bypass the dispatcher and run Supermodel's own ppc_execute()
//   ECA_PPC_MISSLOG=<file>  where to write PCs the dispatcher had to interpret
//                           (default: ppc_misses.txt in the working directory)
//   ECA_PPC_STATS=1         print native/interpreted instruction counts on exit
//   ECA_EXIT_AFTER=<sec>    quit after <sec> seconds of emulated PPC time
//   ECA_LOG_TEXPORT=<file>  log Real3D texture loads (texture port writes, DMA to the
//                           texture port/FIFO with the first words copied, CROM bank
//                           selects). This is how the ROM texture table used by
//                           tools/extract_texture_blocks.py was found.
// Everything else is included first: ppc.cpp defines short macros (RA, SH, MB...)
// that would break later standard headers.
#include "ppc_state.h"
#include <SDL.h>
#include <algorithm>
#include <atomic>
#include <bit>        // before Supermodel.h, which defines a rotl() macro
#include <chrono>
#include <cstddef>
#include <cstdio>
#include <cstdlib>
#include <mutex>
#include <set>
#include <vector>
#include "Supermodel.h"

#define ppc_execute ppc_interp_execute
#define ppc_attach_bus ppc_interp_attach_bus
#include "CPU/PowerPC/ppc.cpp"
#undef ppc_execute
#undef ppc_attach_bus


// --- Layout check against the interpreter's state struct ---------------------------

#define CHECK_FIELD(f) static_assert(offsetof(PPC_REGS, f) == offsetof(PPCRState, f), "PPCRState." #f " out of sync with ppc.cpp")
CHECK_FIELD(r); CHECK_FIELD(pc); CHECK_FIELD(npc); CHECK_FIELD(op); CHECK_FIELD(lr); CHECK_FIELD(ctr);
CHECK_FIELD(xer); CHECK_FIELD(msr); CHECK_FIELD(cr); CHECK_FIELD(srr0); CHECK_FIELD(srr1); CHECK_FIELD(sprg);
CHECK_FIELD(ibat); CHECK_FIELD(dbat); CHECK_FIELD(reserved); CHECK_FIELD(reserved_address);
CHECK_FIELD(interrupt_pending); CHECK_FIELD(tb); CHECK_FIELD(cur_fetch); CHECK_FIELD(fetch); CHECK_FIELD(dec);
CHECK_FIELD(fpscr); CHECK_FIELD(fpr); CHECK_FIELD(sr); CHECK_FIELD(timer_ratio); CHECK_FIELD(dec_trigger_cycle);
CHECK_FIELD(total_cycles); CHECK_FIELD(icount); CHECK_FIELD(cur_cycles); CHECK_FIELD(cycles_per_second);
static_assert(sizeof(PPC_REGS) == sizeof(PPCRState), "PPCRState size differs from PPC_REGS");
#undef CHECK_FIELD

PPCRState *ppcr = reinterpret_cast<PPCRState *>(&ppc);
uint8_t *ppcr_ram = nullptr;
uint8_t ppcr_code_line[0x00800000 >> 8];

namespace
{
  constexpr uint32_t RAM_SIZE = 0x00800000;
  constexpr uint32_t CROM_BASE = 0xFF800000;
  constexpr uint32_t CROM_SIZE = 0x00800000;

  IBus *g_realBus = nullptr;

  // Direct-mapped unit lookup: one slot per instruction word in RAM and fixed CROM
  std::vector<PPCRUnitFn> g_ramTable;
  std::vector<PPCRUnitFn> g_cromTable;

  // RAM unit validation. A unit is trusted while g_ramUnitGen[i] == g_codeGen;
  // any store to a line holding recompiled code bumps g_codeGen.
  uint32_t g_codeGen = 1;
  std::vector<uint32_t> g_ramUnitGen;
  std::vector<uint8_t> g_ramUnitValid;

  bool g_useNative = true;
  bool g_stock = false;
  bool g_stats = false;
  uint64_t g_nativeInstrs = 0;      // approximated from cycles consumed by native units
  uint64_t g_interpInstrs = 0;
  double g_ppcSeconds = 0;          // host time spent inside ppc_execute()
  double g_exitAfterSeconds = 0;
  bool g_quitRequested = false;

  std::mutex g_missMutex;
  std::set<uint32_t> g_misses;
  std::set<uint32_t> g_invalidRamUnits;
  const char *g_missLogPath = "ppc_misses.txt";

  FILE *g_texPortLog = nullptr;

  uint32_t g_dmaSrc = 0, g_dmaDest = 0;

  inline uint32_t Swap32(uint32_t v)
  {
    return (v >> 24) | ((v >> 8) & 0xFF00) | ((v << 8) & 0xFF0000) | (v << 24);
  }

  // Texture loads reach the Real3D either as direct writes to the texture port
  // (0x90xxxxxx) or as Real3D DMA transfers from RAM (registers at 0xC2000000)
  // System registers live at 0xF0100000 with a mirror at 0xFE100000
  inline bool IsSystemRegister(uint32_t a) { return ((a >> 24) == 0xF0 || (a >> 24) == 0xFE) && (a & 0xFFFF00) == 0x100000; }

  inline void LogTexturePort(uint32_t addr, uint32_t data)
  {
    if (!g_texPortLog)
      return;
    if ((addr >> 24) == 0x90)
      fprintf(g_texPortLog, "W %08X %08X pc=%08X lr=%08X\n", addr, data, ppc.pc, ppc.lr);
    else if (IsSystemRegister(addr))
      fprintf(g_texPortLog, "B32 %08X %08X pc=%08X\n", addr, data, ppc.pc);
    // The Real3D DMA registers sit on the little-endian PCI side: values arrive byte-swapped
    else if (addr == 0xC2000000)
      g_dmaSrc = Swap32(data);
    else if (addr == 0xC2000004)
      g_dmaDest = Swap32(data);
    else if (addr == 0xC2000008 && ((g_dmaDest >> 24) == 0x90 || (g_dmaDest >> 24) == 0x94))
    {
      data = Swap32(data);
      fprintf(g_texPortLog, "D %08X -> %08X len=%u bank=%02X pc=%08X lr=%08X:", g_dmaSrc, g_dmaDest, data,
              g_realBus->Read8(0xF0100008), ppc.pc, ppc.lr);
      uint32_t n = std::min<uint32_t>(data, 8);
      for (uint32_t i = 0; i < n; i++)
        fprintf(g_texPortLog, " %08X", g_realBus->Read32(g_dmaSrc + 4 * i));
      fprintf(g_texPortLog, "\n");
    }
  }

  inline void MarkCodeWrite(uint32_t addr)
  {
    if (addr < RAM_SIZE && ppcr_code_line[addr >> 8])
      ++g_codeGen;
  }

  // Wraps the Model 3 bus so stores made by the interpreter also invalidate recompiled RAM code
  class TrackingBus : public IBus
  {
  public:
    UINT8 Read8(UINT32 a) override { return g_realBus->Read8(a); }
    UINT16 Read16(UINT32 a) override { return g_realBus->Read16(a); }
    UINT32 Read32(UINT32 a) override { return g_realBus->Read32(a); }
    UINT64 Read64(UINT32 a) override { return g_realBus->Read64(a); }
    void Write8(UINT32 a, UINT8 d) override
    {
      if (g_texPortLog && IsSystemRegister(a) && (a & 0xFF) == 0x08)   // CROM bank select
        fprintf(g_texPortLog, "B %02X pc=%08X\n", d, ppc.pc);
      g_realBus->Write8(a, d);
      MarkCodeWrite(a);
    }
    void Write16(UINT32 a, UINT16 d) override
    {
      if (g_texPortLog && IsSystemRegister(a))
        fprintf(g_texPortLog, "B16 %08X %04X pc=%08X\n", a, d, ppc.pc);
      g_realBus->Write16(a, d);
      MarkCodeWrite(a);
    }
    void Write32(UINT32 a, UINT32 d) override { LogTexturePort(a, d); g_realBus->Write32(a, d); MarkCodeWrite(a); }
    void Write64(UINT32 a, UINT64 d) override { g_realBus->Write64(a, d); MarkCodeWrite(a); MarkCodeWrite(a + 4); }
    UINT8 IORead8(UINT32 a) override { return g_realBus->IORead8(a); }
    void IOWrite8(UINT32 a, UINT8 d) override { g_realBus->IOWrite8(a, d); }
  };
  TrackingBus g_trackingBus;

  void WriteMissLog()
  {
    std::lock_guard<std::mutex> lock(g_missMutex);
    FILE *fp = g_useNative ? fopen(g_missLogPath, "w") : nullptr;   // other modes would log nothing useful
    if (fp)
    {
      for (uint32_t pc : g_misses)
        fprintf(fp, "%08X\n", pc);
      fclose(fp);
    }
    if (g_stats)
    {
      uint64_t total = g_nativeInstrs + g_interpInstrs;
      fprintf(stderr, "[ppc] units=%u native=%llu interpreted=%llu (%.2f%% native) miss PCs=%zu invalid RAM units=%zu\n",
              ppcr_num_units, (unsigned long long)g_nativeInstrs, (unsigned long long)g_interpInstrs,
              total ? 100.0 * g_nativeInstrs / total : 0.0, g_misses.size(), g_invalidRamUnits.size());
      double emulated = ppc.cycles_per_second ? (double)ppc.total_cycles / ppc.cycles_per_second : 0;
      fprintf(stderr, "[ppc] %.2f s host time in ppc_execute for %.2f s emulated (%.1f%% of real time)\n",
              g_ppcSeconds, emulated, emulated > 0 ? 100.0 * g_ppcSeconds / emulated : 0.0);
    }
  }

  void InitTables()
  {
    static bool done = false;
    if (done)
      return;
    done = true;

    const char *mode = getenv("ECA_PPC_MODE");
    g_stock = mode && !strcmp(mode, "stock");
    g_useNative = !(mode && (!strcmp(mode, "interp") || g_stock));
    if (ppcr_num_units == 0)   // built without a ROM set: every lookup would miss
      g_stock = true, g_useNative = false;
    g_stats = getenv("ECA_PPC_STATS") != nullptr;
    if (const char *p = getenv("ECA_PPC_MISSLOG"))
      g_missLogPath = p;
    if (const char *p = getenv("ECA_EXIT_AFTER"))
      g_exitAfterSeconds = atof(p);
    if (const char *p = getenv("ECA_LOG_TEXPORT"))
      g_texPortLog = fopen(p, "w");

    g_ramTable.assign(RAM_SIZE / 4, nullptr);
    g_cromTable.assign(CROM_SIZE / 4, nullptr);
    for (uint32_t i = 0; i < ppcr_num_units; i++)
    {
      uint32_t a = ppcr_units[i].addr;
      if (a < RAM_SIZE)
        g_ramTable[a / 4] = ppcr_units[i].fn;
      else if (a >= CROM_BASE)
        g_cromTable[(a - CROM_BASE) / 4] = ppcr_units[i].fn;
    }

    g_ramUnitGen.assign(ppcr_num_ram_units, 0);
    g_ramUnitValid.assign(ppcr_num_ram_units, 0);
    memset(ppcr_code_line, 0, sizeof(ppcr_code_line));
    for (uint32_t i = 0; i < ppcr_num_ram_ranges; i++)
    {
      const PPCRRamRange &r = ppcr_ram_ranges[i];
      for (uint32_t a = r.start & ~0xFFu; a < r.start + r.words * 4; a += 256)
        ppcr_code_line[a >> 8] = 1;
    }

    fprintf(stderr, "[ppc] hybrid core: %u recompiled entry points, %u RAM units, native code %s\n",
            ppcr_num_units, ppcr_num_ram_units, g_useNative ? "enabled" : ppcr_num_units ? "disabled (ECA_PPC_MODE)" : "not built (no ROM set at build time)");
    atexit(WriteMissLog);
  }

  inline PPCRUnitFn Lookup(uint32_t pc)
  {
    if (pc < RAM_SIZE)
      return g_ramTable[pc >> 2];
    if (pc >= CROM_BASE)
      return g_cromTable[(pc - CROM_BASE) >> 2];
    return nullptr;
  }

  // One iteration of the interpreter's loop in ppc603.c, verbatim
  inline void InterpretOne()
  {
    ppc.pc = ppc.npc;
    UINT32 opcode = *ppc.op++;
    ppc.npc = ppc.pc + 4;
    switch (opcode >> 26)
    {
    case 19: optable19[(opcode >> 1) & 0x3ff](opcode); break;
    case 31: optable31[(opcode >> 1) & 0x3ff](opcode); break;
    case 59: optable59[(opcode >> 1) & 0x3ff](opcode); break;
    case 63: optable63[(opcode >> 1) & 0x3ff](opcode); break;
    default: optable[opcode >> 26](opcode); break;
    }
    ppc.icount--;
    if (ppc.icount == ppc.dec_trigger_cycle)
    {
      ppc.interrupt_pending |= 0x2;
      ppc603_check_interrupts();
    }
  }

  // Interpret until control leaves straight-line flow (branch or exception), the budget
  // runs out, or the next PC has a recompiled unit.
  void InterpretBlock()
  {
    ppc_change_pc(ppc.npc);
    int start = ppc.icount;
    while (ppc.icount > 0 && !ppc.fatalError)
    {
      UINT32 expected = ppc.npc + 4;
      InterpretOne();
      if (ppc.npc != expected)
        break;
      if (g_useNative && Lookup(ppc.npc))
        break;
    }
    g_interpInstrs += (uint64_t)(start - ppc.icount);
  }
}

// --- API used by the generated code ------------------------------------------------

static inline void EnterSlowPath(uint32_t pc, int icount)
{
  ppc.pc = pc;
  ppc.npc = pc + 4;
  ppc.icount = icount;
}

bool ppcr_ld8_slow(uint32_t ea, uint8_t &out, uint32_t pc, int ic) { EnterSlowPath(pc, ic); out = Bus->Read8(ea); return ppc.npc != pc + 4; }
bool ppcr_ld16_slow(uint32_t ea, uint16_t &out, uint32_t pc, int ic) { EnterSlowPath(pc, ic); out = Bus->Read16(ea); return ppc.npc != pc + 4; }
bool ppcr_ld32_slow(uint32_t ea, uint32_t &out, uint32_t pc, int ic) { EnterSlowPath(pc, ic); out = Bus->Read32(ea); return ppc.npc != pc + 4; }
bool ppcr_ld64_slow(uint32_t ea, uint64_t &out, uint32_t pc, int ic) { EnterSlowPath(pc, ic); out = Bus->Read64(ea); return ppc.npc != pc + 4; }
bool ppcr_st8_slow(uint32_t ea, uint8_t v, uint32_t pc, int ic) { EnterSlowPath(pc, ic); Bus->Write8(ea, v); return ppc.npc != pc + 4; }
bool ppcr_st16_slow(uint32_t ea, uint16_t v, uint32_t pc, int ic) { EnterSlowPath(pc, ic); Bus->Write16(ea, v); return ppc.npc != pc + 4; }
bool ppcr_st32_slow(uint32_t ea, uint32_t v, uint32_t pc, int ic) { EnterSlowPath(pc, ic); Bus->Write32(ea, v); return ppc.npc != pc + 4; }
bool ppcr_st64_slow(uint32_t ea, uint64_t v, uint32_t pc, int ic) { EnterSlowPath(pc, ic); Bus->Write64(ea, v); return ppc.npc != pc + 4; }
void ppcr_code_write(uint32_t) { ++g_codeGen; }

void ppcr_interp_op(uint32_t op)
{
  switch (op >> 26)
  {
  case 19: optable19[(op >> 1) & 0x3ff](op); break;
  case 31: optable31[(op >> 1) & 0x3ff](op); break;
  case 59: optable59[(op >> 1) & 0x3ff](op); break;
  case 63: optable63[(op >> 1) & 0x3ff](op); break;
  default: optable[op >> 26](op); break;
  }
}

// Called at the top of every recompiled RAM unit: is the code in RAM still what we compiled?
bool ppcr_ram_unit_ok(uint32_t idx)
{
  if (g_ramUnitGen[idx] == g_codeGen)
    return g_ramUnitValid[idx] != 0;
  const PPCRRamUnit &u = ppcr_ram_units[idx];
  bool ok = true;
  for (uint32_t i = 0; ok && i < u.num_ranges; i++)
  {
    const PPCRRamRange &r = ppcr_ram_ranges[u.first_range + i];
    ok = memcmp(&ppcr_ram[r.start], &ppcr_ram_code[r.code_offset], r.words * 4) == 0;
  }
  g_ramUnitGen[idx] = g_codeGen;
  g_ramUnitValid[idx] = ok;
  if (!ok)
  {
    std::lock_guard<std::mutex> lock(g_missMutex);
    g_invalidRamUnits.insert(ppcr_ram_ranges[u.first_range].start);
  }
  return ok;
}

// --- Replacements for the renamed interpreter entry points -------------------------

void ppc_attach_bus(IBus *BusPtr)
{
  g_realBus = BusPtr;
  ppc_interp_attach_bus(&g_trackingBus);
}

static int RunDispatcher(int cycles);

int ppc_execute(int cycles)
{
  InitTables();
  if (!ppcr_ram && ppc.fetch)
    ppcr_ram = reinterpret_cast<uint8_t *>(ppc.fetch[0].ptr);  // fetch region 0 is RAM (CModel3::Init)

  auto t0 = std::chrono::steady_clock::now();
  int executed;
  if (g_stock)
    executed = ppc_interp_execute(cycles);
  else
    executed = RunDispatcher(cycles);
  g_ppcSeconds += std::chrono::duration<double>(std::chrono::steady_clock::now() - t0).count();

  if (g_exitAfterSeconds > 0 && !g_quitRequested &&
      (double)ppc.total_cycles >= g_exitAfterSeconds * (double)ppc.cycles_per_second)
  {
    g_quitRequested = true;
    SDL_Event quit = {};
    quit.type = SDL_QUIT;
    SDL_PushEvent(&quit);
  }
  return executed;
}

static int RunDispatcher(int cycles)
{
  // Same setup as the interpreter's ppc_execute()
  ppc.cur_cycles = cycles;
  ppc.icount = cycles;
  ppc.tb_base_icount = cycles + ppc.timer_frac;
  ppc.dec_base_icount = cycles + ppc.timer_frac;
  if ((UINT32)(ppc.dec_base_icount / ppc.timer_ratio) > DEC)
    ppc.dec_trigger_cycle = ppc.dec_base_icount - ((1 + DEC) * ppc.timer_ratio);
  else
    ppc.dec_trigger_cycle = 0x7fffffff;
  ppc_change_pc(ppc.npc);
  ppc603_check_interrupts();

  while (ppc.icount > 0 && !ppc.fatalError)
  {
    PPCRUnitFn fn = g_useNative ? Lookup(ppc.npc) : nullptr;
    if (fn)
    {
      int before = ppc.icount;
      int status = fn(ppc.npc);
      g_nativeInstrs += (uint64_t)(before - ppc.icount);
      // A unit can only end exactly on the decrementer trigger after an instruction
      // that rewrote DEC; mirror the interpreter's per-instruction check here
      if (ppc.icount == ppc.dec_trigger_cycle && before != ppc.icount)
      {
        ppc.interrupt_pending |= 0x2;
        ppc603_check_interrupts();
      }
      if (status == PPCR_EXIT_INTERPRET)
        InterpretBlock();
    }
    else
    {
      if (g_useNative && (ppc.npc < RAM_SIZE || ppc.npc >= CROM_BASE))
      {
        std::lock_guard<std::mutex> lock(g_missMutex);
        g_misses.insert(ppc.npc);
      }
      InterpretBlock();
    }
  }

  // Same epilogue as the interpreter
  ppc.timer_frac = ((ppc.tb_base_icount - ppc.icount) % ppc.timer_ratio);
  ppc.tb += ((ppc.tb_base_icount - ppc.icount) / ppc.timer_ratio);
  DEC -= ((ppc.dec_base_icount - ppc.icount) / ppc.timer_ratio);
  int executed = cycles - ppc.icount;
  ppc.total_cycles += executed;
  ppc.cur_cycles = 0;
  ppc.icount = 0;
  ppc.tb_base_icount = 0;
  ppc.dec_base_icount = 0;
  return executed;
}
